import type { SolutionPageData } from './seoTypes';
import { SERVICE_SOLUTIONS_WEB } from './serviceSolutionsWeb';
import { SERVICE_SOLUTIONS_INFRA } from './serviceSolutionsInfra';
import { SERVICE_SOLUTIONS_OPS } from './serviceSolutionsOps';
import { SUITE_SOLUTIONS_CORE } from './suiteSolutions';
import { SUITE_SOLUTIONS_EXTENDED } from './suiteSolutionsExtended';
import { SEO_SOLUTIONS_MORE } from './seoSolutionsMore';

export const ALL_SERVICE_SOLUTIONS: SolutionPageData[] = [
  ...SERVICE_SOLUTIONS_WEB,
  ...SERVICE_SOLUTIONS_INFRA,
  ...SERVICE_SOLUTIONS_OPS,
  ...SEO_SOLUTIONS_MORE.filter((item) => item.section === 'services'),
];

export const ALL_SUITE_SOLUTIONS: SolutionPageData[] = [
  ...SUITE_SOLUTIONS_CORE,
  ...SUITE_SOLUTIONS_EXTENDED,
  ...SEO_SOLUTIONS_MORE.filter((item) => item.section === 'suite'),
];

export const ALL_SOLUTION_PAGES: SolutionPageData[] = [
  ...ALL_SERVICE_SOLUTIONS,
  ...ALL_SUITE_SOLUTIONS,
];

export function getServiceSolutionsByCategory(
  category: SolutionPageData['category'],
): SolutionPageData[] {
  return ALL_SERVICE_SOLUTIONS.filter((item) => item.category === category);
}

export function getRelatedSolutions(current: SolutionPageData, limit = 6): SolutionPageData[] {
  const sameCategory = ALL_SOLUTION_PAGES.filter(
    (item) => item.slug !== current.slug && item.category === current.category,
  );
  const otherCategory = ALL_SOLUTION_PAGES.filter(
    (item) => item.slug !== current.slug && item.category !== current.category,
  );
  return [...sameCategory, ...otherCategory].slice(0, limit);
}
